import{_ as a,o,c as e,a2 as l}from"./chunks/framework.DpXDHk3d.js";const p=JSON.parse('{"title":"2.4 欧姆定律与电功率","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-4-ou-mu-ding-l-yu-dian-gong-l.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-4-ou-mu-ding-l-yu-dian-gong-l.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-4-ou-mu-ding-l-yu-dian-gong-l.md"};function s(n,t,r,d,h,c){return o(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="_2-4-欧姆定律与电功率" tabindex="-1">2.4 欧姆定律与电功率 <a class="header-anchor" href="#_2-4-欧姆定律与电功率" aria-label="Permalink to &quot;2.4 欧姆定律与电功率&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>有了电流、电压、电阻和串并联的知识,这一节把它们串成<strong>能算账</strong>的公式:<strong>欧姆定律</strong>(电压、电流、电阻的关系)、<strong>电功与电功率</strong>(电干了多少活、耗多少电)。这是机考计算题的&quot;题库&quot;,一定要会算。</p><h2 id="一、欧姆定律-u、i、r-的关系" tabindex="-1">一、欧姆定律:U、I、R 的关系 <a class="header-anchor" href="#一、欧姆定律-u、i、r-的关系" aria-label="Permalink to &quot;一、欧姆定律:U、I、R 的关系&quot;">​</a></h2><h3 id="_1-部分电路欧姆定律" tabindex="-1">1. 部分电路欧姆定律 <a class="header-anchor" href="#_1-部分电路欧姆定律" aria-label="Permalink to &quot;1. 部分电路欧姆定律&quot;">​</a></h3><p>一段不含电源的电路,通过它的电流与两端电压成正比,与电阻成反比:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I = U / R</span></span></code></pre></div><ul><li>I:电流(A);U:电压(V);R:电阻(Ω)。</li></ul><p><strong>变形公式</strong>(考试常来回倒):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U = I × R      电压 = 电流 × 电阻</span></span>
<span class="line"><span>R = U / I      电阻 = 电压 / 电流</span></span></code></pre></div><blockquote><p>💡 <strong>水流类比</strong>:电压是水压,电阻是阻力。水压越高、阻力越小,水流就越大——电流 = 电压 ÷ 电阻。</p></blockquote><h3 id="_2-全电路欧姆定律" tabindex="-1">2. 全电路欧姆定律 <a class="header-anchor" href="#_2-全电路欧姆定律" aria-label="Permalink to &quot;2. 全电路欧姆定律&quot;">​</a></h3><p>把电源**内阻(r)**也算进去,整条闭合回路:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I = E / (R + r)</span></span></code></pre></div><ul><li>E:电源电动势(V);r:电源内阻(Ω);R:外电路总电阻(Ω)。</li></ul><blockquote><p>通俗理解:电池本身也有&quot;内部阻力&quot;(内阻),所以电流要除以&quot;外电阻+内电阻&quot;。考试中大部分题目用<strong>部分电路欧姆定律</strong>,全电路只在&quot;电源内阻&quot;题里出现。</p></blockquote><h2 id="二、电功-电能-电做的-活" tabindex="-1">二、电功(电能):电做的&quot;活&quot; <a class="header-anchor" href="#二、电功-电能-电做的-活" aria-label="Permalink to &quot;二、电功(电能):电做的&quot;活&quot;&quot;">​</a></h2><p><strong>电功</strong>,指电流做的功,也就是电能转化为其他能量(热、光、机械能)的量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>W = U × I × t</span></span></code></pre></div><ul><li>W:电功(焦耳 J);U:电压(V);I:电流(A);t:时间(s)。</li></ul><p><strong>变形公式</strong>:</p><ul><li><code>W = I²·R·t</code>(串联、电流已知时好用)</li><li><code>W = U²·t/R</code>(并联、电压已知时好用)</li></ul><blockquote><p>💡 一度电的概念:<strong>1 kWh(千瓦时)= 1 度电</strong>。1 kWh = 3.6 × 10⁶ J。电表上跳的&quot;度数&quot;就是电功的累计。</p></blockquote><h2 id="三、电功率-电干活的-速度" tabindex="-1">三、电功率:电干活的&quot;速度&quot; <a class="header-anchor" href="#三、电功率-电干活的-速度" aria-label="Permalink to &quot;三、电功率:电干活的&quot;速度&quot;&quot;">​</a></h2><p><strong>电功率</strong>,指单位时间内电流做的功,表示用电器&quot;吃电的速度&quot;。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P = W / t = U × I</span></span></code></pre></div><ul><li>P:功率(瓦 W);1 kW = 1000 W。</li></ul><p><strong>变形公式</strong>:</p><ul><li><code>P = I²·R</code>(电流一定时)</li><li><code>P = U²/R</code>(电压一定时)</li></ul><blockquote><p>💡 <strong>水流类比</strong>:电功是&quot;总共流了多少水&quot;,电功率是&quot;每秒流多少水&quot;。功率越大,单位时间耗电越多。</p></blockquote><p><strong>额定值概念</strong>(第 8 章讲电动机铭牌时会用到):用电器上标的电压、功率叫<strong>额定电压、额定功率</strong>,是它<strong>正常工作</strong>时的数值。电压过高过低都可能损坏设备。</p><h2 id="四、电流的热效应与焦耳定律" tabindex="-1">四、电流的热效应与焦耳定律 <a class="header-anchor" href="#四、电流的热效应与焦耳定律" aria-label="Permalink to &quot;四、电流的热效应与焦耳定律&quot;">​</a></h2><p>电流通过导体时,导体会发热——这就是电流的<strong>热效应</strong>。</p><p><strong>焦耳定律</strong>:电流通过导体产生的热量与电流的平方、电阻、时间成正比:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q = I² · R · t</span></span></code></pre></div><ul><li>Q:热量(焦耳 J);I:电流(A);R:电阻(Ω);t:时间(s)。</li></ul><blockquote><p>⚠️ <strong>重点理解</strong>:热量和<strong>电流的平方</strong>成正比。所以电流只要稍微大一点,发热量就增加很多——这就是为什么过载、短路会导致电气设备迅速发热烧毁。<strong>焦耳定律是后面讲&quot;过载保护、电气火灾&quot;的理论基础。</strong></p></blockquote><h2 id="五、计算例题" tabindex="-1">五、计算例题 <a class="header-anchor" href="#五、计算例题" aria-label="Permalink to &quot;五、计算例题&quot;">​</a></h2><h3 id="例题-1-欧姆定律" tabindex="-1">例题 1:欧姆定律 <a class="header-anchor" href="#例题-1-欧姆定律" aria-label="Permalink to &quot;例题 1:欧姆定律&quot;">​</a></h3><p>一个电阻 R = 20 Ω,两端电压 U = 220 V,求通过电流 I。</p><p><strong>解</strong>:<code>I = U/R = 220/20 = 11 A</code></p><h3 id="例题-2-电功率" tabindex="-1">例题 2:电功率 <a class="header-anchor" href="#例题-2-电功率" aria-label="Permalink to &quot;例题 2:电功率&quot;">​</a></h3><p>一盏灯额定电压 220 V,通过电流 0.5 A,求它的功率。</p><p><strong>解</strong>:<code>P = UI = 220 × 0.5 = 110 W</code></p><h3 id="例题-3-电功-耗电量" tabindex="-1">例题 3:电功(耗电量) <a class="header-anchor" href="#例题-3-电功-耗电量" aria-label="Permalink to &quot;例题 3:电功(耗电量)&quot;">​</a></h3><p>一台 1000 W(1 kW)的电炉,通电 2 小时,耗电多少度?</p><p><strong>解</strong>:<code>W = Pt = 1 kW × 2 h = 2 kWh = 2 度</code></p><h3 id="例题-4-焦耳定律" tabindex="-1">例题 4:焦耳定律 <a class="header-anchor" href="#例题-4-焦耳定律" aria-label="Permalink to &quot;例题 4:焦耳定律&quot;">​</a></h3><p>某电阻 R = 10 Ω,电流 I = 2 A,通电 5 s,产生多少热量?</p><p><strong>解</strong>:<code>Q = I²Rt = 2² × 10 × 5 = 4 × 10 × 5 = 200 J</code></p><h2 id="六、公式速记表" tabindex="-1">六、公式速记表 <a class="header-anchor" href="#六、公式速记表" aria-label="Permalink to &quot;六、公式速记表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>公式</th><th>单位</th></tr></thead><tbody><tr><td>欧姆定律</td><td>I = U/R</td><td>A、V、Ω</td></tr><tr><td>电功</td><td>W = UIt = I²Rt = U²t/R</td><td>J</td></tr><tr><td>电功率</td><td>P = UI = I²R = U²/R</td><td>W</td></tr><tr><td>焦耳定律</td><td>Q = I²Rt</td><td>J</td></tr></tbody></table><blockquote><p>💡 记忆技巧:看到&quot;电流、电阻&quot;想到 I²R;看到&quot;电压、电阻&quot;想到 U²/R;功率=电压×电流,P=UI 是基础公式。</p></blockquote><h2 id="七、考点提示" tabindex="-1">七、考点提示 <a class="header-anchor" href="#七、考点提示" aria-label="Permalink to &quot;七、考点提示&quot;">​</a></h2><ul><li>✅ 欧姆定律 <code>I = U/R</code> 及其变形必须熟练,计算题基础。</li><li>✅ 焦耳定律 <code>Q = I²Rt</code>:热量与<strong>电流平方</strong>成正比,是过载、短路发热的原理。</li><li>✅ 1 度电 = 1 kWh = 3.6×10⁶ J。</li><li>✅ 额定功率 = 额定电压 × 额定电流(正常工作时)。</li><li>⚠️ 易混点:W(电功,焦耳)和 W(功率单位&quot;瓦特&quot;)字母相同,注意区分——看上下文。</li></ul><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><ul><li>欧姆定律 I=U/R,是&quot;电压推动电流、电阻阻碍电流&quot;的定量表达。</li><li>电功 W=UIt 量电能,电功率 P=UI 量快慢,1 度电 = 1 kWh。</li><li>焦耳定律 Q=I²Rt 说明电流平方与热量成正比,解释过载短路的危险。</li></ul><h2 id="九、自测练习" tabindex="-1">九、自测练习 <a class="header-anchor" href="#九、自测练习" aria-label="Permalink to &quot;九、自测练习&quot;">​</a></h2><ol><li>(单选)欧姆定律的表达式是()。 A. I = UR　B. I = U/R　C. I = R/U　D. U = IR</li><li>(计算)某电阻两端电压 36 V,电流 0.6 A,求电阻值 R。</li><li>(单选)电流通过导体产生的热量,与()成正比。 A. 电流　B. 电流的平方　C. 电压的平方　D. 电阻的倒数</li><li>(判断)1 度电等于 1 kWh。( )</li><li>(计算)一台 220 V、200 W 的灯泡正常工作时,通过的电流约是多少?</li><li>(单选)功率的单位是()。 A. 焦耳　B. 瓦特　C. 安培　D. 伏特</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。I = U/R。</li><li>R = U/I = 36/0.6 = <strong>60 Ω</strong>。</li><li><strong>B</strong>。焦耳定律 Q = I²Rt,热量与电流的平方成正比。</li><li><strong>√</strong>。1 度电 = 1 kWh = 3.6×10⁶ J。</li><li>I = P/U = 200/220 ≈ <strong>0.91 A</strong>。</li><li><strong>B</strong>。功率单位是瓦特(W)。</li></ol></details>`,60)])])}const g=a(i,[["render",s]]);export{p as __pageData,g as default};
